library(plyr)
library(Seurat)
library(SeuratWrappers)
library(harmony)
library(stringr)})

#Read data
sample1<-readRDS(file = '/share/home/liny/Project/personality/SY_wangwenbiao_spleen_mouse_20250521/samplerds3/fiterrds//18m-G489.rds')
sample2<-readRDS(file = '/share/home/liny/Project/personality/SY_wangwenbiao_spleen_mouse_20250521/samplerds3/fiterrds//18m-G490.rds')
sample3<-readRDS(file = '/share/home/liny/Project/personality/SY_wangwenbiao_spleen_mouse_20250521/samplerds3/fiterrds//18m-G491.rds')
sample4<-readRDS(file = '/share/home/liny/Project/personality/SY_wangwenbiao_spleen_mouse_20250521/samplerds3/fiterrds//18m-G756.rds')
sample5<-readRDS(file = '/share/home/liny/Project/personality/SY_wangwenbiao_spleen_mouse_20250521/samplerds3/fiterrds//18m-G757.rds')
sample6<-readRDS(file = '/share/home/liny/Project/personality/SY_wangwenbiao_spleen_mouse_20250521/samplerds3/fiterrds//18m-G760.rds')
sample7<-readRDS(file = '/share/home/liny/Project/personality/SY_wangwenbiao_spleen_mouse_20250521/samplerds3/fiterrds//18m-G761.rds')
merge_data<-merge(x = sample1, y=c(sample2,sample3,sample4,sample5,sample6,sample7) , add.cell.ids = c('18m-G489','18m-G490','18m-G491','18m-G756','18m-G757','18m-G760','18m-G761'))
#merge
s.genes <- str_to_title(cc.genes$s.genes)
g2m.genes <- str_to_title(cc.genes$g2m.genes)
merge_data <- merge_data %>% Seurat::NormalizeData(verbose = FALSE) %>% FindVariableFeatures(selection.method = 'vst', nfeatures = 2000) %>% CellCycleScoring(s.features = s.genes, g2m.features = g2m.genes) %>% ScaleData(verbose = FALSE,vars.to.regress = c('S.Score', 'G2M.Score')) %>% RunPCA(verbose = FALSE)
integrated_data <- merge_data %>% RunHarmony('orig.ident')
#add group
sample_group_data<-data_frame(sample=c('18m-G489','18m-G490','18m-G491','18m-G756','18m-G757','18m-G760','18m-G761'),group=c('Mock','Mock','Mock','Microplastics','Microplastics','Microplastics','Microplastics'))
integrated_data@meta.data$group<-mapvalues(integrated_data@meta.data$orig.ident,sample_group_data$sample,sample_group_data$group)
#cluster
#ElbowPlot(integrated_data)
integrated_data <- FindNeighbors(integrated_data, reduction = 'harmony',dims = 1:20)
integrated_data <- FindClusters(integrated_data, resolution = 0.5)
integrated_data <- RunTSNE(integrated_data, reduction = 'harmony', dims = 1:20)
integrated_data <- RunUMAP(integrated_data, reduction = 'harmony', dims = 1:20)
integrated_data@meta.data$orig.ident<-factor(integrated_data@meta.data$orig.ident,levels = c('18m-G489','18m-G490','18m-G491','18m-G756','18m-G757','18m-G760','18m-G761'))
integrated_data@meta.data$group<-factor(integrated_data@meta.data$group,levels = unique(c('Mock','Mock','Mock','Microplastics','Microplastics','Microplastics','Microplastics')))
integrated_data@assays$RNA@scale.data<-matrix()
saveRDS(integrated_data,file = paste0('/share/home/liny/Project/personality/SY_wangwenbiao_spleen_mouse_20250521/Seurat/7Harmony/merge_rds/merge_data.rds'))
color_panel<-c('#53A85F','#58A4C3','#AB3282','#8C549C','#BD956A','#57C3F3','#6778AE','#F3B1A0','#F1BB72','#DCC1DD','#E95C59','#625D9E','#F7F398','#E63863','#5F3D69','#C5DEBA','#CCE0F5','#B53E2B','#AA9A59','#E39A35','#91D0BE','#23452F','#E4C755','#585658','#C1E6F3','#D6E7A3','#712820','#CCC9E6','#3A6963','#68A180','#476D87','#9FA3A8','#968175')
p1<-DimPlot(integrated_data,label = T,cols = color_panel,raster = F,pt.size = 0.4,reduction = 'umap')
p2<-DimPlot(integrated_data,label = T,split.by = 'group',cols = color_panel,raster = F,pt.size = 0.4,reduction = 'umap')
p3<-DimPlot(integrated_data,label = T,split.by = 'orig.ident',cols = color_panel,raster = F,pt.size = 0.4,ncol = 4,reduction = 'umap')
Idents(integrated_data)<-integrated_data@meta.data$orig.ident
p4<-DimPlot(integrated_data,pt.size = 0.4,raster = F,reduction = 'umap')
Idents(integrated_data)<-integrated_data@meta.data$group
p44<-DimPlot(integrated_data,pt.size = 0.4,raster = F,reduction = 'umap')
if ("percent.mt" %in% colnames(integrated_data@meta.data)){
integrated_data[['percent.rp']]<-PercentageFeatureSet(integrated_data, pattern = '^rpl|^rps')
p5<-FeaturePlot(integrated_data,features = c('nFeature_RNA','nCount_RNA','percent.mt','percent.rp'),reduction = 'umap')}else{
integrated_data[['percent.mt']]<-PercentageFeatureSet(integrated_data, pattern = '^mt-')
integrated_data[['percent.rp']]<-PercentageFeatureSet(integrated_data, pattern = '^rpl|^rps')
p5<-FeaturePlot(integrated_data,features = c('nFeature_RNA','nCount_RNA','percent.mt','percent.rp'),reduction = 'umap')}
